var $corr = 0; //desired correction to heading; used to steer
storage var $spd :number; //maximum speed
storage var $auto :number;
storage var $light :text;

var $prev = 0;
var $heading = input_number(3,6) ;navinstrument heading.


include "cede.main.xc"
include "screen.xc"


function @headingDeviation() : number

	// Normalize the correction to the range [-180, 180]
	if ($corr > 180) 
		$corr -= 360;
	else
		if ($corr < -180) 
			$corr += 360;
	return $corr;

update

	if(input_number(3,7))
		if(!$prev)
			$auto = !$auto

	if($auto)
		$spd += input_number(3,3)
	else
		$heading = $currentheading
	if(input_number(3,1) || input_number(3,2) ) ;manual input, reset heading to avoid ship trying to move back
		$heading = $currentheading

	$prev = input_number(3,7)

	$corr = $heading - $currentheading


	var $speed = input_number(4,0);

	;When
	var $maxturn = 35;
	if($speed > -1)
		var $direction = input_number(3,5)
		if($direction < -0.01 )
			if($heading < 1)
				$heading += 360
			if($corr > -$maxturn)
				$heading -= min(4, abs($corr + $maxturn))
		else 
			if($direction > 0.01)
				if($heading > 358)
					$heading -= 360;			
				if($corr < $maxturn)
					$heading += min(4, abs($maxturn - $corr))


	;update the light.
	if($light.on)
		output_number(0,0,1)
	else
		output_number(0,0,0)

	if($light.red)	
		output_number(0,1,1+ $light.red)
	if($light.green)	
		output_number(0,2,1+ $light.green)
	if($light.blue)	
		output_number(0,3,1+ $light.blue)		


	;print(text("correction currently is: {}",@headingDeviation()))
